contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: whether the test calls as an admin (bool makeAdmin), the description string
    function run(bool makeAdmin, string calldata description) public payable {
        // set up admin flag for this contract address if requested
        if (makeAdmin) {
            // c.isAdmin is public mapping; only accessible via external call to set mapping in C is not provided.
            // However the C contract exposes isAdmin public variable but no setter; the deployer (checker) may set it.
            // We attempt to call newEmergencyOracle and record whether it reverts.
        }

        bool reverted;
        address oracleAddress;
        // Try calling newEmergencyOracle and capture revert
        try c.newEmergencyOracle(description) {
            reverted = false;
            // If it didn't revert, the event was emitted and an EmergencyOracle was created.
            // The emitted event cannot be read here, but we can inspect the newly created contract by scanning
            // recent code isn't available; however the function returns nothing. But the spec of C creates
            // new EmergencyOracle(msg.sender, description) so owner() should equal msg.sender.
            // We can attempt to locate the created contract address by reading logs is impossible.
            // Instead, we can assert that if the call succeeded then c.isAdmin(address(this)) must be true
            // (since only admins can call). Use public getter isAdmin.
            // Also we can attempt to find the last created EmergencyOracle by checking address(this).balance unaffected.
            // To keep to the allowed observations, we will require the relationship: success => c.isAdmin(address(this))==true
        } catch {
            reverted = true;
        }

        bool amIAdmin = c.isAdmin(address(this));

        // General rule asserted: call succeeds iff this contract is admin. If succeeded, returned state observable is that isAdmin stays true.
        // This encodes: non-admin calls revert; admin calls do not revert.
        assert(reverted == (!amIAdmin));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // param: description for newEmergencyOracle
    function run(string calldata description) public payable {
        // no preconditions on parameters
        bool beforeIsAdmin = c.isAdmin(address(this));

        bool reverted;
        // perform the state-changing call (may revert) and capture whether it reverted
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool afterIsAdmin = c.isAdmin(address(this));

        // General rule: calling newEmergencyOracle either reverts, or if it doesn't revert it does not flip this contract's isAdmin flag from true to false.
        // That is: it's invalid for the call to succeed and for beforeIsAdmin to be true while afterIsAdmin is false.
        assert(!(reverted == false && beforeIsAdmin == true && afterIsAdmin == false));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: description for newEmergencyOracle
    function run(string calldata description) public payable {
        // No preconditions on parameters
        // Ensure this contract is an admin before calling: if not, try to make it an admin by calling nothing (can't), so record before-state.
        bool beforeIsAdmin = c.isAdmin(address(this));

        // perform the state-changing call (may revert) and capture whether it reverted
        bool reverted;
        address newOracleAddr = address(0);
        try c.newEmergencyOracle(description) {
            reverted = false;
            // If succeeded, we can read emitted NewEmergencyOracle via nothing, but we can observe created contract by reading code size or calling known public getter.
            // C does not return the new address, but event was emitted; however we can scan by checking that some newly-created contract exists at any address is impossible here.
            // Instead, rely on the fact that EmergencyOracle has a public description() and owner() — we can try to find the oracle by guessing that the last created contract is at address(this)?? Not possible.
            // But newEmergencyOracle uses 'new EmergencyOracle(msg.sender, description)' and then emits the address. The test can still attempt to read description by iterating possible addresses is not allowed.
            // Workaround: when newEmergencyOracle succeeds, it must not have changed c.isAdmin(address(this)) (reasonable invariant to check). Also the new oracle when created will have owner == address(this) (msg.sender). We can attempt to detect that by calling owner() on potential address, but we don't know it.
            // Simpler reachable invariant: if call succeeds, c.isAdmin(address(this)) must stay true if it was true before (new oracle creation shouldn't revoke admin). We'll assert that.
            newOracleAddr = address(0); // placeholder, not used further
        } catch {
            reverted = true;
        }

        bool afterIsAdmin = c.isAdmin(address(this));

        // General rule: Either the call reverted, or if it succeeded then it did not flip this contract's isAdmin from true to false.
        // Express: not(succeeded && beforeIsAdmin && !afterIsAdmin)
        assert(!(reverted == false && beforeIsAdmin == true && afterIsAdmin == false));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public entry: attempt to call newEmergencyOracle with arbitrary description
    function run(string calldata description) public payable {
        // No precondition on parameters
        // Observe admin status before the call
        bool beforeIsAdmin = c.isAdmin(address(this));

        // Perform the state-changing call; capture whether it reverted
        bool reverted;
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe admin status after the call
        bool afterIsAdmin = c.isAdmin(address(this));

        // General rule: if the caller was not an admin before, the call (whether it reverted or not)
        // must not have granted admin status to the caller. In other words: beforeIsAdmin == false implies afterIsAdmin == false.
        // Expressed without implication: !(beforeIsAdmin == false && afterIsAdmin == true)
        assert(!(beforeIsAdmin == false && afterIsAdmin == true));
    }

    receive() external payable {}
