contract InvMutTest {
    C c;
    event NewEmergencyOracle(address owner, address newOracle);

    constructor(C _c) { c = _c; }

    // params: whether caller is admin_before_call and a description for oracle
    function run(bool makeAdmin, string calldata description) public payable {
        // set up admin mapping: only public state available is c.isAdmin(address)
        // We are the InvMutTest contract (msg.sender for calls to c)
        // Make sure initial state: if makeAdmin true, set isAdmin[msg.sender] by calling c.isAdmin is public mapping
        // but mapping is writeable only by external callers; C has no setter, so rely on possibility that test harness sets it
        // To accommodate both, we'll try the call and detect revert.

        bool reverted;
        // attempt to call newEmergencyOracle; it should succeed iff isAdmin[this]==true
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe whether c reports this address as admin
        bool observedAdmin = c.isAdmin(address(this));

        // If observedAdmin is true then call must not have reverted; if false, call must have reverted.
        // Additionally, when not reverted, the event NewEmergencyOracle must have been emitted by the call.
        // We cannot directly read past events, but the function emits NewEmergencyOracle with msg.sender as owner
        // and creates an EmergencyOracle whose owner is the admin (msg.sender). We can observe by calling the
        // auto-generated owner() on the newly created oracle address — but we don't have that address unless we parse logs.
        // The specification below captures the essential invariant: reverted == !observedAdmin

        assert(reverted == (!observedAdmin));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We take a description; no Ether involved.
    function run(string calldata description) public payable {
        // Observe admin status before the call
        bool adminBefore = c.isAdmin(address(this));

        bool reverted;
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe admin status after the call
        bool adminAfter = c.isAdmin(address(this));

        // General rule: the call may only succeed when caller is admin (so if not adminBefore it must have reverted),
        // and the call does not change the isAdmin mapping for the caller (adminBefore == adminAfter).
        assert((!adminBefore && reverted) || (adminBefore && !reverted) && (adminBefore == adminAfter));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Take a description for the oracle. No Ether required.
    function run(string calldata description) public payable {
        // No precondition on c; only require on params if desired
        require(bytes(description).length <= 2000, "desc too long");

        // Observe admin status before the call
        bool adminBefore = c.isAdmin(address(this));

        // Try the mutating call which may revert
        bool reverted;
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe admin status after the call
        bool adminAfter = c.isAdmin(address(this));

        // General rule to assert:
        // - The call must not flip the caller's admin flag (adminBefore == adminAfter)
        // - If the call reverted then that's allowed; if it didn't revert then it must have produced a NewEmergencyOracle event whose newOracle address is non-zero.
        //   We cannot read events here, so we express the non-zero-newOracle requirement by checking that when the call succeeded, creating the EmergencyOracle contract at the emitted address would have non-zero code size.
        //   However we cannot access the emitted address. Instead we assert only observable rule: successful call implies it didn't revert and (as intended) should have deployed a contract, so address(c).balance is unchanged by this call (no Ether transferred). Combining these, we assert the safety property:
        //   The call cannot flip admin, and if it succeeded it did not revert.

        // Since we cannot directly observe the emitted address or events here, we assert that admin flag is preserved and that revert corresponds to not-admin-before.
        // More permissive: if caller was not admin then call must revert; if caller was admin then call must not revert.
        // This encodes the intended access control behavior as a general rule.

        assert((!adminBefore && reverted && adminBefore == adminAfter) || (adminBefore && !reverted && adminBefore == adminAfter));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Take an arbitrary description string; no Ether involved.
    function run(string calldata description) public payable {
        // only parameter constraint to keep execution reachable
        require(bytes(description).length <= 4096, "description too long");

        // Observe the caller's admin status before the mutating call
        bool adminBefore = c.isAdmin(address(this));

        // Attempt the potentially-reverting call; we must ensure the call is a top-level statement
        bool reverted;
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe the caller's admin status after the call
        bool adminAfter = c.isAdmin(address(this));

        // General invariant: the call must not flip the caller's admin flag
        assert(adminBefore == adminAfter);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an arbitrary description and an amount to attempt to send (but newEmergencyOracle is nonpayable),
    // ensuring address(this) has enough balance if a positive amount is provided for other potential uses.
    function run(string calldata description, uint256 fundAmount) public payable {
        require(bytes(description).length <= 4096, "description too long");
        // Ensure the test contract has the requested balance to be safe (checker funds the caller normally).
        if (fundAmount > 0) {
            require(address(this).balance >= fundAmount, "insufficient balance for fundAmount");
        }

        // Observe C's Ether balance before the call
        uint256 balanceBefore = address(c).balance;

        // Call may revert; capture revert flag. The call is top-level as required.
        bool reverted;
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe C's Ether balance after the call
        uint256 balanceAfter = address(c).balance;

        // General invariant: newEmergencyOracle must not transfer Ether to or from c, so balance stays the same.
        assert(balanceBefore == balanceAfter);
    }

    receive() external payable {}
}

