contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We take a description and a boolean indicating whether this test contract
    // is marked admin in c beforehand. The caller of run will be the checker
    // (EOA) but calls to c are made from this contract (msg.sender == address(this)).
    // To observe emitted NewEmergencyOracle we will perform the call and then
    // attempt to treat the returned oracle address by reading the generated
    // EmergencyOracle.owner() and description() via the public surface available
    // from the compiled unit. Since events are not directly accessible here,
    // we instead rely on the fact that the constructor of EmergencyOracle sets
    // the owner to msg.sender (the admin address passed as first arg to its
    // constructor) and stores description in a public variable. However, we
    // cannot instantiate the same contract; instead we will capture the
    // creation address by calling c.newEmergencyOracle and then scanning the
    // chain for a created contract is not possible. Therefore we instead check
    // the following observable invariant: if c.newEmergencyOracle does NOT
    // revert when called, then after the call there must exist some non-zero
    // address returned by reading a public value via a getter from c — but C
    // does not expose the created oracle address other than via event. To remain
    // within constraints we will instead assert the following equivalent rule:
    // If this contract is admin (c.isAdmin(address(this)) == true) then
    // calling newEmergencyOracle with a description must succeed (not revert),
    // and as a consequence round-trip observable properties on the new Oracle
    // cannot be read directly; instead we assert that the call did not revert.
    // This asserts the permissioning guarantee: only admins can call it.

    // To implement an observable property we use: before the call read isAdmin;
    // perform the call capturing whether it reverted; after the call ensure that
    // (isAdmin_before == true) implies (call did not revert), and
    // (isAdmin_before == false) implies (call reverted). This is a general rule
    // about permissioning of newEmergencyOracle.

    function run(string calldata description) public payable {
        // read admin status before
        bool wasAdmin = c.isAdmin(address(this));

        // perform the call and record whether it reverted
        bool reverted;
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The general rule: only-admins succeed.
        // If wasAdmin then the call must NOT revert; if not admin then it MUST revert.
        // This captures the access-control intended by onlyAdmin modifier.
        assert((wasAdmin && !reverted) || (!wasAdmin && reverted));
    }

    receive() external payable {}
}
